from pathlib import Path
from PIL import Image
import numpy as np
from scipy.ndimage import binary_propagation
import base64,json
p=Path(__file__).parent;r=p.parent/'revision-corpulence';ref=p.parent/'refs-spritecollab';assets={}
def data(f):return 'data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode()
for key,name in [('base','repos-trois-quart-01.png'),('idle2','Anime-Idle-02.png'),('walk2','Anime-Walk-02.png')]:
 a=np.array(Image.open(r/name).convert('RGB')).astype('int16');c=np.median(a[:25,-25:].reshape(-1,3),axis=0);m=np.sqrt(((a-c)**2).sum(axis=2))<35;s=np.zeros(m.shape,bool);s[0,:]=m[0,:];s[-1,:]=m[-1,:];s[:,0]=m[:,0];s[:,-1]=m[:,-1];bg=binary_propagation(s,mask=m,structure=np.ones((3,3)));im=Image.fromarray(np.dstack((a.astype('uint8'),np.where(bg,0,255).astype('uint8'))),'RGBA'); im=im.resize((160,201),Image.Resampling.NEAREST);f=p/(key+'.png');im.save(f);assets[key]=data(f)
for key in ['Idle','Walk']:assets[key]=data(ref/(key+'-Anim.png'))
t='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Méga-Tsareena · modèle validé</title><style>body{background:#14201b;color:#e7f2e4;font:16px system-ui;margin:0}main{max-width:1000px;margin:auto;padding:22px}h1{margin:4px 0}.tag{color:#c3e598;font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}p,li{line-height:1.5}.sub{color:#b9cebc}.cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{background:#20362a;padding:14px;border:1px solid #42644b;border-radius:14px;text-align:center}h2{font-size:18px}canvas{width:100%;max-width:400px;height:auto;background:#c7d9bb;image-rendering:pixelated;border-radius:10px}.actions{display:flex;gap:8px;margin:15px 0;flex-wrap:wrap}button{background:#385d44;color:white;border:1px solid #70916e;padding:10px 15px;border-radius:8px;cursor:pointer;font-weight:bold}button.active{background:#c2df9e;color:#213e25}.info{background:#273c2e;border-left:4px solid #b5d395;padding:12px 16px;border-radius:10px;margin-top:18px}a{color:#d0f1a6}@media(max-width:600px){.cols{grid-template-columns:1fr}}</style></head><body><main><div class="tag">Reprise depuis le sprite validé</div><h1>Méga-Tsareena · premières poses</h1><p class="sub">Comparaison en trois-quarts : la forme normale sert de référence à gauche, le modèle Méga validé à droite.</p><div class="actions"><button data-action="Idle">Repos</button><button data-action="Walk">Déplacement</button></div><div class="cols"><section class="panel"><h2>Tsareena · SpriteCollab</h2><canvas id="normal" width="360" height="240"></canvas><p id="norm"></p></section><section class="panel"><h2>Méga · même modèle</h2><canvas id="mega" width="360" height="240"></canvas><p id="megatxt"></p></section></div><div class="info"><strong>Avancement réel :</strong> une seconde pose de repos et une pose de déplacement ont été générées depuis le modèle validé. Le déplacement Méga répète deux dessins sur quatre temps : ce n’est pas encore une séquence complète. Les essais d’attaque, charge et balayage qui modifiaient le design ou les membres n’ont pas été intégrés.</div><h2>À poursuivre</h2><ul><li>Terminer les poses intermédiaires de chaque animation et les contrôler par rapport au modèle validé.</li><li>Reprendre les sept autres directions, puis vérifier les bras, les jambes, la couronne et les points d’ancrage.</li><li>Réintégrer uniquement les animations cohérentes dans la simulation de donjon et préparer les planches SpriteCollab.</li></ul><p class="sub">Référence : <a href="https://github.com/PMDCollab/SpriteCollab/tree/master/sprite/0763">SpriteCollab · Tsareena #763</a>, crédit baronessfaron. Les images générées originales sont conservées intactes.</p></main><script>
const data=__DATA__,images={};for(const [k,v] of Object.entries(data)){let i=new Image;i.src=v;images[k]=i}const normal=document.querySelector('#normal').getContext('2d'),mega=document.querySelector('#mega').getContext('2d');normal.imageSmoothingEnabled=false;mega.imageSmoothingEnabled=false;let action='Idle',start=performance.now();const durs={Idle:[30,30],Walk:[8,10,8,10]},maps={Idle:['base','idle2'],Walk:['base','walk2','base','walk2']};function choose(n){action=n;start=performance.now();document.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.action===n));document.querySelector('#norm').textContent=n==='Idle'?'2 images · 30 / 30 ticks':'4 images · 8 / 10 / 8 / 10 ticks';document.querySelector('#megatxt').textContent=n==='Idle'?'2 poses générées':'2 poses générées, répétées sur 4 temps'}document.querySelectorAll('button').forEach(b=>b.onclick=()=>choose(b.dataset.action));function bg(c){c.fillStyle='#637f59';c.fillRect(0,0,360,240);for(let y=0;y<8;y++)for(let x=0;x<12;x++){c.fillStyle=(x+y)%2?'#91aa80':'#99b388';c.fillRect(x*30,y*30,30,30);c.fillStyle='#a8bd98';c.fillRect(x*30,y*30,30,1)}c.fillStyle='#314a32';c.beginPath();c.ellipse(180,201,48,10,0,0,Math.PI*2);c.fill()}function draw(t){let d=durs[action],sum=d.reduce((a,b)=>a+b,0),v=Math.floor((t-start)*60/1000)%sum,i=0;while(i<d.length-1&&v>=d[i]){v-=d[i];i++}bg(normal);bg(mega);let n=images[action],m=images[maps[action][i]];if(n.complete&&n.naturalWidth){normal.drawImage(n,i*32,56,32,56,116,64,128,224)}if(m.complete&&m.naturalWidth)mega.drawImage(m,100,18,160,201);requestAnimationFrame(draw)}choose('Idle');requestAnimationFrame(draw);
</script></body></html>'''
(p/'Apercu-modele-valide.html').write_text(t.replace('__DATA__',json.dumps(assets,separators=(',',':'))),encoding='utf8');print('OK',len(t),'template chars',[(k,len(v)) for k,v in assets.items()])
